const fs=require("fs"),p=require("path");
function walk(d,o=[]){for(const e of fs.readdirSync(d,{withFileTypes:true})){const f=p.join(d,e.name);if(e.isDirectory())walk(f,o);else if(f.endsWith(".md"))o.push(f);}return o;}
const files=[...walk("docs/superpowers"),...walk(".github"),...["README.md","CONTRIBUTING.md","AGENTS.md","CLAUDE.md"].filter(fs.existsSync)];
for (const f of files){const t=fs.readFileSync(f,"utf8");
